const fs = require("fs");

// Turnstile 的 action / cData 会被烤进 token。站点拿 siteverify 回包里的
// action/cdata 跟自己会话里存的那一份比对, 对不上就判无效 —— 所以必须在 render 时就带上。
// 两者都没传时返回 "{}", 页面行为与改动前完全一致。
// JSON 里的 < 转义掉, 免得取值里带 </script> 把假页面截断。
// 历史上这里一律 reject("字符串"), 到了上层取 err.message 就是 undefined, 接口只剩一个
// {"code":500} —— 真正的原因全丢了。统一改成带状态码的 Error。
function fail(message, statusCode) {
  const e = new Error(message);
  e.statusCode = statusCode;
  return e;
}

function renderOptions(action, cData) {
  const o = {};
  if (action) o.action = String(action);
  if (cData) o.cData = String(cData);
  return JSON.stringify(o).replace(/</g, "\\u003c");
}

function solveTurnstileMin({ url, proxy, siteKey, action, cData }) {
  return new Promise(async (resolve, reject) => {
    if (!url) return reject(fail("Missing url parameter", 400));
    if (!siteKey) return reject(fail("Missing siteKey parameter", 400));

    // 检查浏览器是否已初始化。这两种都是"过会儿再来"而不是"请求有问题", 所以是 503 不是 500。
    if (!global.browser) {
      if (global.browserInitFailed) {
        return reject(fail("浏览器初始化失败，请检查Chrome安装和配置(headless:false 需要图形会话)", 503));
      }
      return reject(fail("浏览器正在初始化中，请稍后重试", 503));
    }

    let context = null;
    let contextClosed = false;

    try {
      // 使用上下文池获取上下文
      if (global.contextPool && typeof global.contextPool.getContext === 'function') {
        context = await global.contextPool.getContext();
      } else {
        // 回退到直接创建
        context = await global.browser
          .createBrowserContext({
            proxyServer: proxy ? `http://${proxy.host}:${proxy.port}` : undefined,
          })
          .catch(() => null);
      }

      if (!context) return reject(fail("Failed to create browser context", 503));

      let isResolved = false;

      const closeContext = async () => {
        if (!contextClosed && context) {
          try {
            contextClosed = true;
            // 使用上下文池释放上下文
            if (global.contextPool && typeof global.contextPool.releaseContext === 'function') {
              await global.contextPool.releaseContext(context);
            } else {
              // 回退到直接关闭
              await context.close();
            }
          } catch (err) {
            console.error("Error releasing context:", err.message);
          }
        }
      };

      var cl = setTimeout(async () => {
        if (!isResolved) {
          await closeContext();
          reject(fail("Timeout Error: 超过 " + (global.timeOut || 180000) + "ms 未拿到 token", 504));
        }
      }, global.timeOut || 180000);
      const page = await context.newPage();

      if (proxy?.username && proxy?.password)
        await page.authenticate({
          username: proxy.username,
          password: proxy.password,
        });

      await page.setRequestInterception(true);

      page.on("request", async (request) => {
        if (
          [url, url + "/"].includes(request.url()) &&
          request.resourceType() === "document"
        ) {
          await request.respond({
            status: 200,
            contentType: "text/html",
            body: String(
              require("fs").readFileSync(require("path").join(__dirname, "../data/fakePage.html"))
            )
              .replace(/<site-key>/g, siteKey)
              .replace(/<turnstile-options>/g, renderOptions(action, cData)),
          });
        } else {
          await request.continue();
        }
      });

      // 优化页面加载和token等待
      await page.goto(url, {
        waitUntil: "domcontentloaded",
        timeout: 30000
      });

      // 优化的token等待逻辑，减少阻塞时间
      let token = null;
      const maxAttempts = 2; // 减少重试次数，提高并发
      const baseTimeout = 45000; // 减少基础超时到45秒
      
      for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        try {
          console.log(`🔄 Turnstile attempt ${attempt}/${maxAttempts} for ${new URL(url).hostname}`);
          
          // 并行等待Turnstile脚本和token
          const tokenPromise = page.waitForSelector('[name="cf-response"]', {
            timeout: baseTimeout + (attempt * 5000) // 较小的递增时间
          });
          
          const scriptPromise = page.waitForFunction(() => {
            return window.turnstile && typeof window.turnstile.render === 'function';
          }, { timeout: 10000 }).catch(() => {
            console.log('⚠️  Turnstile script not loaded quickly, continuing...');
          });
          
          // 并行等待，提高效率
          await Promise.race([
            tokenPromise,
            scriptPromise.then(() => tokenPromise)
          ]);
          
          // 快速验证token
          token = await page.evaluate(() => {
            const element = document.querySelector('[name="cf-response"]');
            const value = element?.value;
            
            // 优化的token验证
            if (value && value.length > 10 && 
                !value.includes('undefined') && 
                !value.includes('null') &&
                value.indexOf('.') > 0) { // Turnstile token通常包含点
              return value;
            }
            return null;
          });
          
          if (token) {
            console.log(`✅ Turnstile token obtained on attempt ${attempt} (${token.length} chars)`);
            break;
          } else {
            console.log(`❌ Invalid token on attempt ${attempt}, retrying...`);
            if (attempt < maxAttempts) {
              // 更短的等待时间
              await new Promise(resolve => setTimeout(resolve, 1000));
              // 快速刷新
              await page.reload({ waitUntil: 'domcontentloaded', timeout: 15000 });
            }
          }
          
        } catch (attemptError) {
          console.log(`❌ Attempt ${attempt} failed: ${attemptError.message}`);
          if (attempt === maxAttempts) {
            throw attemptError;
          }
          // 更快的失败恢复
          await page.reload({ waitUntil: 'domcontentloaded', timeout: 15000 }).catch(() => {});
          await new Promise(resolve => setTimeout(resolve, 1500));
        }
      }
      
      isResolved = true;
      clearTimeout(cl);
      await closeContext();
      if (!token || token.length < 10) return reject(fail("Failed to get token: widget 没有产出有效 token", 502));
      return resolve(token);
      
    } catch (e) {
      console.log(e);
      isResolved = true;
      clearTimeout(cl);
      if (context && !contextClosed) {
        try {
          contextClosed = true;
          await context.close();
        } catch (err) {
          console.error("Error closing context:", err.message);
        }
      }
      reject(e instanceof Error ? e : fail(String(e && e.message || e), 500));
    }
  });
}
module.exports = solveTurnstileMin;